(4, NULL, 'gaming', 'Gaming Accessories', '<p>Dominate your game with RGB mechanical keyboards, high-DPI gaming mice, pro headsets, and cooling pads.</p>', 'Buy Gaming Accessories in Pakistan | Multan Tech', 'Level up your setup with gaming accessories in Pakistan. Fast delivery in Multan, Lahore, Karachi & all cities.', 'gaming accessories in pakistan', 40, 1, 1),
